 * @param attHp       血量
 * @param attMp       蓝量
 * @param pAtk        物理攻击
 * @param mAtk        魔法攻击
 * @param pDef        物理防御
 * @param mDef        魔法防御
 * @param acc         命中
 * @param avoid       回避
 * @param hands       攻击速度
 * @param speed       移动速度
 * @param jump        跳跃
 * @param upgradeSlot 可升级次数
 * @param expireTime  失效时间，-1为不失效 来自 @leevccc 的建议，传值则为分钟
 */
function sendEquipment(fashionItemId) {
    cm.getPlayer().gainEquip(fashionItemId,
        5,
        5,
        5,
        5,
        100,
        100,
        5,
        5,
        0,
        0,
        0,
        0,
        0,
        0,
        0,
        0,
        -1
    );
}
function sendSuperMegaphone(player, typeOrTitle, titleOrContent, content) {
    if (player.checkoutBroadcast()) {
        return;
    }
    var title = content === undefined ? typeOrTitle : titleOrContent;
    var message = content === undefined ? titleOrContent : content;
    var fullMessage = "[" + title + "] : " + message;
    var Server = Java.type("org.gms.net.server.Server");
    var PacketCreator = Java.type("org.gms.util.PacketCreator");

    // 5072000（高质地喇叭）使用类型 3 的全服喇叭封包。
    Server.getInstance().broadcastMessage(
        player.getWorld(),
        PacketCreator.serverNotice(
            3,
            player.getClient().getChannel(),
            player.getName() + " : " + fullMessage,
            true
        )
    );
}

BeiDouSpecial/任务/每日任务:
/**
 * 每日任务脚本
 * 功能：每日10轮任务，按等级匹配道具要求，支持提交/跳过，依赖AccountExtendValue的24小时自动清除机制重置
 */

var status = -1;
var currentRound = 1; // 当前轮次
const maxRounds = 10; // 最大轮次
const CashPoint1Num = 1000; // 点券奖励
const MesoNum = 20; // 金币奖励,单位W
var selectedItemId = 0; // 当前任务道具ID
var requiredItemCount = 0; // 当前任务所需道具数量
var 额外奖励次数 = 8;
var 声望 = 6000;
// 定义每日签到奖励物品信息
var 奖励道具集合 = [
    {id: 2029004, qty: 1},//三倍经验
    {id: 2029002, qty: 1}//双倍经验
];

// 存储键名定义
const ROUND_KEY = "每日任务当前第几轮";
const TOTAL_COMPLETE_KEY = "每日任务总完成轮数";
const ITEM_ID_KEY = "每日任务当前道具ID";
const ITEM_COUNT_KEY = "每日任务当前道具数量";

// 任务道具配置（按等级段划分）
var itemPools = [
    [[4000019, 10], [4000012, 10], [4000002, 15], [4000215, 10], [4000034, 10], [4000331, 10]],    //20 绿色蜗牛壳, 绿蘑菇盖, 蝴蝶结, 斧头,蛇皮,仙人掌的花
    [[4000007, 10], [4000020, 15], [4000196, 10], [4000106, 10]],   // 20级 火独眼兽之尾, 野猪尖牙, 木板, 玩具熊猫的棉花团
    [[4000032, 10], [4000073, 10], [4000108, 10], [4000096, 10], [4000110, 10], [4000031, 10]],   // 40级 鳄鱼皮, 独角狮硬角,熊猫娃娃, 硬胡桃,木马骑兵的剑,诅咒娃娃
    [[4000014, 10], [4000023, 10], [4000178, 10], [4000060, 10], [4000205, 10]],   // 30级 龙的头骨, 冰独眼兽之尾, 钢甲猪盔甲,月光精灵的月块,绷带
    [[4000069, 10], [4000022, 10], [4000051, 10], [4000440, 10]],   // 60级 僵尸丢失的臼齿, 石块, 野狼之尾, 粗糙的皮革
    [[4000074, 10], [4000295, 10], [4000289, 10], [4000027, 10]],   // 70级 黑色飞狮尾, 鳄鳄的皮, 猫咪娃娃、怪猫的眼
    [[4000226, 10], [4000028, 5], [4000232, 10], [4000242, 10]],   // 80级 莱西毛球、月牙牛魔王的角、半人马的火花、恶魔绵羊尾巴
    [[4000262, 10], [4000477, 10], [4000430, 10]],   // 90级 有裂痕的背壳 海盗头盔 怪虫迪波之角
    [[4000184, 10], [4000135, 10], [4000268, 10], [4000269, 10], [4000270, 10]],   // 100级 奶油烤章鱼 大海贼王的帽子 飞龙的翅膀 飞龙的腮 飞龙的指甲 大海贼王的帽子
    [[4000274, 15], [4000434, 15]]   // 110级 断裂的角 大花草
];


function start() {
    // 加载存储的任务数据
    loadTaskData();
    status = -1;
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode === -1) {
        // 关闭对话框时保存当前进度
        saveTaskProgress();
        cm.dispose();
        return;
    }

    // 处理状态流转
    if (mode === 1) {
        status++;
    } else {
        status--;
    }
    // 主界面逻辑
    if (status === 0) {
        if (currentRound > maxRounds) {
            cm.sendOk("今日10轮任务已全部完成，明天再来挑战吧！\r\n\r\n");
            cm.dispose();
            return;
        }
        // 显示当前轮次任务信息和操作选项
        let text = `#k每日任务 第 #r${currentRound}/${maxRounds} #k轮\r\n\r\n` +
            `#b每轮奖励：#k\r\n` +
            `- ${CashPoint1Num} 点券\r\n` +
            `- ${MesoNum} w金币\r\n\r\n` +
            获取奖励文本() +
            `#b当前任务要求：\r\n` +
            `#b#i${selectedItemId}# #t${selectedItemId}# × ${requiredItemCount}\r\n\r\n` +
            `#k请选择操作：\r\n` +
            `#r#L0#提交任务#l\r\n` +  // 使用换行符分隔选项，避免索引识别错误
            `#k#L1#跳过本轮(不获取奖励)#l`;
        cm.sendSimple(text);
    } else if (status === 1) {
        if (selection === 0) {//点击提交
            completeTask();
        } else if (selection === 1) {//点击跳过
            // 显示跳过确认提示
            cm.sendYesNo(`确定要跳过第 ${currentRound} 轮任务吗？\r\n跳过本轮将不会获得任何奖励，直接进入下一轮。`);
        }
    } else if (status === 2) {//确认跳过
        // 确认跳过（mode=1），取消跳过（mode=0）
        if (mode === 1) {
            skipTask();
        }
    }
}

function 获取奖励文本() {
    let text = "#b第10轮，并且当天总完成次数大于8轮：#k\r\n";
    奖励道具集合.forEach(reward => {
        text += `- #v${reward.id}##t${reward.id}# x ${reward.qty}\r\n`;
    });
    text += `- 学院声望 x #r${声望}\r\n`;
    text += "\r\n";
    return text;
}

/**
 * 加载存储的任务数据
 */
function loadTaskData() {
    const savedRound = cm.getAccountExtendValue(ROUND_KEY, true);
    currentRound = savedRound ? parseInt(savedRound) : 1;
    currentRound = savedRound <= 0 ? 1 : parseInt(savedRound);

    const savedTotalComplete = cm.getAccountExtendValue(TOTAL_COMPLETE_KEY, true);
    // 初始化总完成次数（默认0）
    totalCompleteCount = savedTotalComplete ? parseInt(savedTotalComplete) : 0;

    const savedItemId = cm.getAccountExtendValue(ITEM_ID_KEY, true);
    selectedItemId = savedItemId ? parseInt(savedItemId) : 0;
    const savedItemCount = cm.getAccountExtendValue(ITEM_COUNT_KEY, true);
    requiredItemCount = savedItemCount ? parseInt(savedItemCount) : 0;

    if (selectedItemId === 0 || requiredItemCount === 0) {
        generateTask();
        saveTaskProgress();
    }
}

/**
 * 重置每日任务状态
 */
function resetDailyTask() {
    currentRound = 1;
    totalCompleteCount = 0; // 重置总完成次数
    selectedItemId = 0;
    requiredItemCount = 0;
}

/**
 * 保存当前任务进度
 */
function saveTaskProgress() {
    cm.saveOrUpdateAccountExtendValue(ROUND_KEY, currentRound.toString(), true);
    cm.saveOrUpdateAccountExtendValue(TOTAL_COMPLETE_KEY, totalCompleteCount.toString(), true); // 保存总完成次数
    cm.saveOrUpdateAccountExtendValue(ITEM_ID_KEY, selectedItemId.toString(), true);
    cm.saveOrUpdateAccountExtendValue(ITEM_COUNT_KEY, requiredItemCount.toString(), true);
}

/**
 * 根据玩家等级生成对应任务道具
 */
function generateTask() {
    const playerLevel = cm.getPlayer().getLevel();
    let availableItems = [];

    // 按等级筛选可用道具池
    if (playerLevel < 20) {
        availableItems = [...itemPools[0]];
    } else if (playerLevel < 30) {
        availableItems = [...itemPools[0], ...itemPools[1]];
    } else if (playerLevel < 40) {
        availableItems = [...itemPools[0], ...itemPools[1], ...itemPools[2]];
    } else if (playerLevel < 50) {
        availableItems = [...itemPools[1], ...itemPools[2], ...itemPools[3]];
    } else if (playerLevel < 60) {
        availableItems = [...itemPools[2], ...itemPools[3], ...itemPools[4]];
    } else if (playerLevel < 70) {
        availableItems = [ ...itemPools[3], ...itemPools[4], ...itemPools[5]];
    } else if (playerLevel < 80) {
        availableItems = [...itemPools[4], ...itemPools[5], ...itemPools[6]];
    } else if (playerLevel < 90) {
        availableItems = [...itemPools[5], ...itemPools[6], ...itemPools[7]];
    } else if (playerLevel < 100) {
        availableItems = [...itemPools[6], ...itemPools[7], ...itemPools[8]];
    } else {
        availableItems = [...itemPools[7], ...itemPools[8], ...itemPools[9]];
    }

    // 随机选择一个道具
    const randomIndex = Math.floor(Math.random() * availableItems.length);
    selectedItemId = availableItems[randomIndex][0];
    requiredItemCount = availableItems[randomIndex][1];
}

/**
 * 处理任务完成逻辑
 */
function completeTask() {
    if (cm.haveItem(selectedItemId, requiredItemCount)) {
        // 检查背包空间
        if (cm.isNotCanHold(2)) {
            return;
        }
        // 1. 总完成次数+1并保存
        totalCompleteCount++;

        // 2. 进入下一轮
        const completedRound = currentRound; // 记录当前完成的轮次
        currentRound++;

        // 3. 扣除道具
        cm.gainItem(selectedItemId, -requiredItemCount);
        // 4. 发放基础奖励
        cm.gainMeso(MesoNum * 10000);
        cm.getPlayer().getCashShop().gainCash(1, CashPoint1Num);

        // 5. 第10轮任务完成时，判断是否发放额外道具（总完成次数>8）
        let extraRewardText = "";
        if (completedRound === maxRounds) {
            // 总完成次数>8时发放额外道具
            if (totalCompleteCount >= 额外奖励次数) {
                发放道具();
                //发放6000声望
                // cm.getPlayer().getFamilyEntry().gainReputation(声望, true);
                extraRewardText = `- 额外奖励：\r\n`;
                奖励道具集合.forEach(item => {
                    extraRewardText += `  #v${item.id}##t${item.id}# x ${item.qty}\r\n`;
                });
                extraRewardText += `  学院声望 x #r${声望}\r\n`;
                sendSuperMegaphone(cm.getPlayer(), "每日任务", `恭喜玩家${cm.getPlayer().getName()}完成每日任务10次!`)
            } else {
                extraRewardText = `- 今日总完成次数不足${额外奖励次数}次，未获得额外道具奖励\r\n`;
            }
        }

        // 6. 生成下一轮任务（如果未完成全部轮次）
        if (currentRound <= maxRounds) {
            generateTask();
        }

        // 7. 保存进度并提示
        saveTaskProgress();
        status = -1;
        let text = `#b恭喜完成第 #r${completedRound}/${maxRounds} #b轮任务（成功完成${totalCompleteCount}轮任务）！\r\n\r\n` +
            `获得奖励：\r\n` +
            `- #r${CashPoint1Num} #b点券\r\n` +
            `- #r${MesoNum} #bW金币\r\n`;
        if (completedRound === maxRounds) {
            text += extraRewardText;
        }
        cm.sendNext(text);
    } else {
        // 道具不足时返回主界面
        cm.sendOk(
            `你的 #t${selectedItemId}# #r数量不足\r\n` +
            `#b需要：#r${requiredItemCount} #b个  当前持有：#r${cm.getItemQuantity(selectedItemId) || 0} #b个\r\n\r\n`
        );
        cm.dispose();
    }
}

/**
 * 发放额外道具奖励
 */
function 发放道具() {
    奖励道具集合.forEach(item => {
        cm.gainItem(item.id, item.qty);
    });
}

/**
 * 跳过当前任务（带确认流程）
 */
function skipTask() {
    // 进入下一轮并生成新任务（跳过不增加总完成次数）
    currentRound++;
    if (currentRound <= maxRounds) {
        generateTask();
    }
    saveTaskProgress();
    // 显示跳过成功提示后返回主界面
    status = -1;
    action(1, 0, 0);
}
function sendSuperMegaphone(player, typeOrTitle, titleOrContent, content) {
    if (player.checkoutBroadcast()) {
        return;
    }
    var title = content === undefined ? typeOrTitle : titleOrContent;
    var message = content === undefined ? titleOrContent : content;
    var fullMessage = "[" + title + "] : " + message;
    var Server = Java.type("org.gms.net.server.Server");
    var PacketCreator = Java.type("org.gms.util.PacketCreator");

    // 5072000（高质地喇叭）使用类型 3 的全服喇叭封包。
    Server.getInstance().broadcastMessage(
        player.getWorld(),
        PacketCreator.serverNotice(
            3,
            player.getClient().getChannel(),
            player.getName() + " : " + fullMessage,
            true
        )
    );
}

BeiDouSpecial/任务/狩猎:
/**
 * 狩猎任务UI脚本
 * 仅作为界面展示和任务提交
 * 支持两种任务类型：
 * - type=1: 收集物品，需要玩家提交道具
 * - type=2: 打BOSS，第一个击杀该BOSS的玩家获得奖励
 */

// 导入Java类
var HuntTaskAutoPublisher = Java.type('org.gms.server.timer.HuntTaskAutoPublisher');
var Server = Java.type('org.gms.net.server.Server');
var InventoryType = Java.type('org.gms.client.inventory.InventoryType');

// 全局变量
var status = -1;

/**
 * 入口函数
 */
function start() {
    action(1, 0, 0);
}

/**
 * 动作处理函数
 */
function action(mode, type, selection) {
    if (mode === 1) {
        status++;
    } else if (mode === -1) {
        status--;
    } else {
        cm.dispose();
        return;
    }

    try {
        switch (status) {
            case 0:
                showMainMenu();
                break;
            case 1:
                handleSubmit(selection);
                break;
            default:
                cm.dispose();
                break;
        }
    } catch (e) {
        cm.sendOk("系统错误：" + e.message);
        cm.dispose();
    }
}

/**
 * 显示主菜单
 */
function showMainMenu() {
    var publisher = HuntTaskAutoPublisher.getInstance();
    var currentTask = publisher.getCurrentTask();

    var text = "#e#r【狩猎任务系统】#n#k\r\n\r\n";
    text += "#d玩法说明：\r\n";

    // 获取配置信息
    var taskInterval = publisher.getTaskInterval() / 3600; // 转换为小时
    var rewardItems = publisher.getRewardItems();

    text += "1.每隔" + taskInterval + "小时发布一次任务\r\n";
    text += "2.全服只有第一个完成的人能获取奖励：\r\n#b";
    text += "   - 金币 +" + publisher.getGoldReward() + "\r\n";
    text += "   - 经验 +" + publisher.getExpReward() + "\r\n";
    text += "   - 点券 +" + publisher.getCashReward() + "#d\r\n";
    text += "3.并且有几率获取如下道具：#r\r\n";

    if (rewardItems != null && rewardItems.length > 0) {
        for (var i = 0; i < rewardItems.length; i++) {
            var item = rewardItems[i];
            text += "   - #z" + item.getItemId() + "#"+"  x"+item.getCount()+"\r\n";
            if (i < rewardItems.length - 1) {
                text += "";
            }
        }
    } else {
        text += "无#d";
    }
    text += "\r\n";

    text += "\r\n";
    // 检查任务是否存在（BOSS任务有bossId，收集任务有itemId）
    if (!currentTask || (currentTask.getItemId() === 0 && currentTask.getBossId() === 0)) {
        text += "#r当前没有进行中的狩猎任务#k\r\n";
        text += "等待系统自动发布...\r\n";
        cm.sendOk(text);
        cm.dispose();
        return;
    }

    // 判断是否是BOSS狩猎任务
    if (currentTask.isBossTask()) {
        // BOSS狩猎任务
        text += "#e任务类型：狩猎BOSS#n\r\n";
        text += "目标怪物：" + currentTask.getItemName() + "\r\n";

        if (currentTask.isCompleted()) {
            text += "\r\n#r任务状态：已完成#k\r\n";
            text += "#b完成玩家：" + currentTask.getCompletedByName() + "#k\r\n";
            text += "#r下次刷新：" + formatTime(currentTask.getEndTime()) + "#k\r\n";
        } else {
            text += "\r\n#b任务状态：进行中#k\r\n";
            text += "#r下次刷新：" + formatTime(currentTask.getEndTime()) + "#k\r\n";
            text += "\r\n#r第一个击杀该BOSS的玩家直接获得奖励！#k";
        }
        cm.sendOk(text);
        cm.dispose();
        return;
    }

    // 收集物品任务
    var player = cm.getPlayer();
    var itemCount = player.getItemQuantity(currentTask.getItemId(), false);
    text += "#b任务类型：收集物品#n\r\n";
    text += "#v" + currentTask.getItemId() + "# #z" + currentTask.getItemId() + "#\r\n";
    text += "需求数量：" + currentTask.getNeedCount() + "个\r\n";
    text += "你的持有：" + itemCount + "个\r\n";

    if (currentTask.isCompleted()) {
        text += "\r\n#r任务状态：已完成#k\r\n";
        text += "#b完成玩家：" + currentTask.getCompletedByName() + "\r\n";
        text += "#r下次刷新：" + formatTime(currentTask.getEndTime()) + "#k\r\n";
        cm.sendOk(text);
        cm.dispose();
        return;
    }

    text += "\r\n#b任务状态：进行中#k\r\n";
    text += "#r下次刷新：" + formatTime(currentTask.getEndTime()) + "#k\r\n";

    var canSubmit = itemCount >= currentTask.getNeedCount();

    if (canSubmit) {
        text += "\r\n#b#L1#提交任务#l#k\r\n";
    }else {
        text += "\r\n#e道具数量不足，无法提交任务#k\r\n";
    }
    cm.sendSimple(text);
}

/**
 * 格式化时间戳为 时:分 格式
 */
function formatTime(timestamp) {
    var date = new java.util.Date(timestamp);
    var hours = date.getHours();
    var minutes = date.getMinutes();

    if (hours < 10) {
        hours = "0" + hours;
    }
    if (minutes < 10) {
        minutes = "0" + minutes;
    }

    return hours + ":" + minutes;
}

/**
 * 处理提交
 */
function handleSubmit(selection) {
    if (selection === 0) {
        status = -1;
        start();
        return;
    }

    if (selection === 1) {
        submitTask();
        return;
    }

    cm.dispose();
}

/**
 * 提交任务
 */
function submitTask() {
    var publisher = HuntTaskAutoPublisher.getInstance();
    var currentTask = publisher.getCurrentTask();
    var player = cm.getPlayer();

    // 检查任务是否存在（BOSS任务有bossId，收集任务有itemId）
    if (!currentTask || (currentTask.getItemId() === 0 && currentTask.getBossId() === 0)) {
        cm.sendOk("#r当前没有进行中的狩猎任务#k");
        cm.dispose();
        return;
    }

    // BOSS任务不能通过这里提交
    if (currentTask.isBossTask()) {
        cm.sendOk("#rBOSS狩猎任务无需提交！\r\n请击杀对应BOSS即可获得奖励。#k");
        cm.dispose();
        return;
    }

    if (currentTask.isCompleted()) {
        cm.sendOk("#r任务已被其他玩家完成！\r\n你未能抢先完成。#k");
        cm.dispose();
        return;
    }

    var itemCount = player.getItemQuantity(currentTask.getItemId(), false);

    if (itemCount < currentTask.getNeedCount()) {
        cm.sendOk("#r道具数量不足！\r\n需要：" + currentTask.getNeedCount() + "个\r\n当前：" + itemCount + "个\r\n还差：" + (currentTask.getNeedCount() - itemCount) + "个#k");
        cm.dispose();
        return;
    }

    // 调用Java方法检测是否可以完成任务
    var canComplete = publisher.canCompleteTask(player);

    if (canComplete === 1) {
        cm.sendOk("#r任务已被其他玩家完成！\r\n你未能抢先完成。#k");
        cm.dispose();
        return;
    }

    if (canComplete === 2) {
        cm.sendOk("#r任务已过期！#k");
        cm.dispose();
        return;
    }

    if (canComplete === 3) {
        cm.sendOk("#r道具数量不足！#k");
        cm.dispose();
        return;
    }

    // 扣除道具（使用负数表示扣除）
    cm.gainItem(currentTask.getItemId(), -currentTask.getNeedCount());

    // 标记任务完成
    publisher.markTaskCompleted(player.getName());

    // 显示奖励（从配置文件读取奖励值）
    var text = "#e#r【狩猎任务完成！】#n#k\r\n\r\n";
    text += "恭喜你完成了狩猎任务！\r\n\r\n";
    text += "奖励如下：\r\n";
    text += "#b金币 +" + publisher.getGoldReward() + "#k\r\n";
    text += "#b经验 +" + publisher.getExpReward() + "#k\r\n";
    text += "#b点券 +" + publisher.getCashReward() + "#k\r\n";

    cm.sendOk(text);
    cm.dispose();
}

