// 每格定宽（半角单位）+ 格间隔，一行三格总宽约 36，远小于对话框宽度（约 54）
var 菜单格宽 = 12;
var 菜单格间隔 = 2;

var OldTitle = "\t\t\t\t\t#e#k欢迎来到#r[任务大厅]#k系统#n\t\t\t\t\r\n";
var status = -1;
var i = 0;

function start() {
