    action(1, 0, 0)
}

function action(mode, type, selection) {
    if (mode === 1) {
        status++;
    } else if (mode === -1) {
        status--;
    } else {
        cm.dispose();
        return;
    }
    if (status === 0) {
        let text = OldTitle;
        text += "#b \r\n";
        text += 菜单行([[0, "每日任务"], [1, "主线任务"], [2, "世界任务"]]);
        cm.sendSimple(text);
    } else if (status === 1) {
        doSelect(selection);
    } else {
        cm.dispose();
    }
}

// 一行菜单：半角 [] 括号 + 空格定宽对齐（制表符宽度不可控，不要改回去）
function 菜单行(条目列表) {
    let 行 = "";
    for (let n = 0; n < 条目列表.length; n++) {
        行 += "#L" + 条目列表[n][0] + "##b[" + 条目列表[n][1] + "]#k#l";
        if (n < 条目列表.length - 1) {
            let 补 = 菜单格宽 + 菜单格间隔 - 取显示宽("[" + 条目列表[n][1] + "]");
            行 += " ".repeat(补 > 0 ? 补 : 菜单格间隔);
        }
    }
    return 行 + "\r\n";
}

// 半角宽度：中日韩全角字符按 2 计，其余按 1 计
function 取显示宽(文本) {
    let 宽 = 0;
    for (let n = 0; n < 文本.length; n++) {
        宽 += 文本.charCodeAt(n) > 0x2E80 ? 2 : 1;
    }
    return 宽;
}

