    switch (selection) {
        case 0:
            openNpc("任务/每日任务");
            break;
        case 1:
            openNpc("任务/主线任务");
            break;
        case 2:
            openNpc("任务/世界任务");
            break;
        default:
            cm.sendOk("该功能暂不支持，敬请期待！");
            cm.dispose();
    }
}

