                cm.sendOk("兑换成功。");
                sendSuperMegaphone(cm.getPlayer(), 6, "副本兑换", `恭喜玩家${cm.getPlayer().getName()}兑换了一个【${cm.getPlayer().getItemName(item)}】!`);
            } else {
                cm.sendOk("背包空间不足。");
            }
        }
        cm.dispose();
    }
}
