let targetItem = null;      // 材料装备

function start() {
    action(1, 0, 0);
}

function action(mode, type, selection) {
    // 关闭对话/取消操作（优先处理，避免无效流程）
    if (mode == -1) {
        cm.dispose();
        return;
    } else if (mode == 0) {
        cm.dispose();
        return;
    }
    status++;
    if (status === 1) {
