function action(mode, type, selection) {
    if (mode === 1) {
        status++;
    } else {
        cm.dispose();
        return;
    }
    if (status === 0) {
        let text = OldTitle;
        text += " \r\n";
        text += "#b#L1#耳环#l\t\r\n\r\n";
        text += "#L2#眼睛#l\t\r\n\r\n";
        text += "#L3#鞋子#l\t\r\n\r\n";
        text += "#L4#帽子#l\t\r\n\r\n";
        text += "#L5#武器#l\t\r\n\r\n";
        text += "\r\n\r\n\t#r以下还未实现#k\t\r\n\r\n";
        text += "#L7#披风#l\t\r\n\r\n";
        text += "#L8#手套#l\t\r\n\r\n";
        text += "#L9#腰带#l\t\r\n\r\n";
        text += "#L10#项链#l\t\r\n\r\n";
        cm.sendSimple(text);
    } else if (status === 1) {
        doSelect(selection);
    } else if (status === 2) {
        确认制作(selection);
    } else if (status === 3) {
        doCraftItem();
    } else {
        cm.dispose();
    }
}

function doSelect(selection) {
    switch (selection) {
        case 1:
            选择的制作列表 = 耳环;
            展示物品制作列表();
            break;
        case 2:
            选择的制作列表 = 眼睛;
            展示物品制作列表();
            break;
        case 3:
            选择的制作列表 = 鞋子;
            展示物品制作列表();
            break;
        case 4:
            选择的制作列表 = 帽子;
            展示物品制作列表();
            break;
        case 5:
