    //展示物品
    let text = OldTitle + "\r\n请选择要制作的物品：\r\n\r\n";
    选择的制作列表.forEach((item, index) => {
        // 拼接目标物品信息
        text += `#L${index}##b制作#v${item.id}#  #r#z${item.id}##k\r\n`;
        text += "\r\n";
    });
    cm.sendSimple(text);
