 */
var status = -1;

/** 成品 id -> 应继承的上一阶材料 id（与装备制作.js 腰带配方一致） */
var 腰带合成上一级 = {
    1132296: 1132115,
    1132211: 1132296,
    1132212: 1132211,
    1132213: 1132212,
    1132214: 1132213,
    1132215: 1132214
