var newStatsDes;

function start() {
    status = -1;
    selectedUpgradeIndex = -1; // 初始化选中索引
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode === 1) {
        status++; // 正向操作（点击确定/选择项）
    } else if (mode === -1) {
        status--; // 反向操作（点击取消）
    } else {
        cm.dispose(); // 关闭对话
        return;
    }

    // 根据状态流转处理
    switch (status) {
        case 0:
            main(); // 显示主菜单（装备属性+升级历史）
            break;
        case 1:
            if (selection === 999) {
                洗练范围说明();
                return;
            }
            // 选中升级记录后，先检查道具是否充足
            selectedUpgradeIndex = selection;
            if (checkRequiredItems()) {
                // 消耗道具
                consumeRequiredItems();
                // 道具充足，进入属性预览确认页
                showAttrConfirmPage();
            } else {
                cm.sendOk("洗练所需材料不足,无法洗练");
