function start() {
    status = -1;
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode < 1) {
        cm.dispose();
    } else {
        status++;
        if (cm.getPlayer().getMap().getId() == 910010100) { //Clear map
            if (status == 0) {
                cm.sendNext("你好！我是#p1012113#。我们所在的地方附近有个猪猪村庄。那里的猪非常吵闹且难以控制，甚至从旅行者那里偷走了许多武器。它们被原来的村庄赶了出来，现在躲在猪猪村庄里。");
            } else if (status == 1) {
                if (cm.isEventLeader()) {
                    cm.sendYesNo("你觉得和你的队员一起去那里给那些吵闹的猪一个教训怎么样？");
                } else {
                    cm.sendOk("感兴趣吗？告诉你的队长来和我谈谈，然后前往那里！");
                    cm.dispose();

                }
            } else if (status == 2) {
                cm.getEventInstance().startEventTimer(5 * 60000);
                cm.getEventInstance().warpEventTeam(910010200);

                cm.dispose();

            }
        } else if (cm.getPlayer().getMap().getId() == 910010200) { //Bonus map
            if (status == 0) {
                cm.sendYesNo("你现在想离开猪猪村庄吗？");
            } else {
                cm.warp(910010400);
                cm.dispose();

            }
        } else if (cm.getPlayer().getMap().getId() == 910010300) { //Exit map
            if (status == 0) {
                cm.sendOk("你现在将被传送出去，感谢你的帮助！");
            } else {
                cm.warp(100000200);
                cm.dispose();

            }
        }
    }
}

npc/1012114:
/*
Growlie (that fatass uhh.. hungry lion or whatever)

@author FightDesign (RageZONE)
@author Ronan
*/

var status = 0;
var chosen = -1;
let 副本类型 = 7;
let maxCount = 50;
let reward = 800;

function clearStage(stage, eim) {
    eim.setProperty(stage + "stageclear", "true");
    eim.showClearEffect(true);

    eim.giveEventPlayersStageReward(stage);
}

function start() {
    status = -1;
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode < 0) {
        cm.dispose();

    } else {
        if (mode == 0 && status == 0) {
            cm.dispose();
            return;
        }
        if (mode == 0) {
            status += ((chosen == 2) ? 1 : -1);
        } else {
            status++;
        }

        if (status == 0) {
            if (cm.isEventLeader()) {
                let completedCount = cm.getPQEnteredCount(副本类型);
                let remainingCount = maxCount - completedCount;
                if (remainingCount < 0) {
                    remainingCount = 0;
                }
                let tip = "吼！我是#p1012114#，时刻准备守护这片地方。你来这儿干什么？\r\n";
                tip += "\r\n";
                tip += `#b注意每天只有前#r${maxCount}#b次才有奖励\r\n`;
                tip += `#r您当前已完成${completedCount}次，还有${remainingCount}次\r`;
                tip += "\r\n\r\n";
                tip += "#b#L0# 请告诉我这片地方是怎么回事。#l\r\n#L1# 我带来了 #t4001101#。#l\r\n#L2# 我想离开这片地方。#l";
                cm.sendSimple(tip);
            } else {
                cm.sendSimple("吼！我是#p1012114#，时刻准备守护这片地方。你来这儿干什么？\r\n#b#L0# 请告诉我这片地方是怎么回事。#l\r\n#L2# 我想离开这片地方。#l");
            }
        } else if (status == 1) {
            if (chosen == -1) {
                chosen = selection;
            }
            if (chosen == 0) {
                cm.sendNext("这片地方可以说是绝佳之处，每逢满月你都能品尝到月兔制作的美味年糕。");
            } else if (chosen == 1) {
                if (cm.haveItem(4001101, 5)) {
                    cm.sendNext("哦……这不是月兔做的年糕吗？请把年糕给我。嗯……这些看起来很美味。下次再带更多的 #b#t4001101##k 来找我哦。一路平安！");
                } else {
                    cm.sendOk("我建议你检查一下，确保你确实收集了 #b5 个 #t4001101##k。");
                    cm.dispose();
                }
            } else if (chosen == 2) {
                cm.sendYesNo("你确定要离开吗？");
            } else {
                cm.dispose();

            }
        } else if (status == 2) {
            if (chosen == 0) {
                cm.sendNextPrev("在这片区域收集遍布各处的迎月花种子，然后把种子种在月牙附近的土壤里，就能看到迎月花盛开。迎月花有六种，每种都需要不同的土壤。土壤必须适合花的种子，这一点至关重要。");
            } else if (chosen == 1) {
                let completedCount = cm.getPQEnteredCount(副本类型);
                if (completedCount < maxCount) {
                    cm.addPqPoints();
                    cm.gainItem(4001101, -5);
                    cm.getPlayer().getCashShop().gainCash(1, reward);
                    cm.getPlayer().dropMessage(5, `恭喜获得${reward}点卷,今天已完成${completedCount + 1}次`);
                    //获取经验
                    cm.gainPQExp(10);
                    cm.gainMeso(50 * 10000);
                }
                //记录当天副本完成次数
                cm.recordEntryPQ(副本类型);
                var eim = cm.getEventInstance();
                clearStage(1, eim);

                var map = eim.getMapInstance(cm.getPlayer().getMapId());
                map.killAllMonstersNotFriendly();

                eim.clearPQ();
                cm.dispose();
            } else {
                if (mode == 1) {
                    cm.warp(910010300);
                } else {
                    cm.sendOk("那你最好给我收集些美味的年糕，因为时间不多了，吼！");
                }
                cm.dispose();
            }
        } else if (status == 3) {
            if (chosen == 0) {
                cm.sendNextPrev("当迎月花盛开时，满月就会升起，那时月兔就会出现并开始舂米。你的任务是击退怪物，确保月兔能专心制作出最美味的年糕。");
            }
        } else if (status == 4) {
            if (chosen == 0) {
                cm.sendNextPrev("我希望你和你的队员们合作，给我弄来 10 个年糕。我强烈建议你在规定时间内把年糕给我。");
            }
        } else {
            cm.dispose();
        }
    }
}

