        if (status == 0) {
            cm.sendYesNo("圣诞老人告诉我来到这里，只是他没有告诉我什么时候……我希望我来的时间对了！哦！顺便说一下，我是鲁尼，我可以带你去#b幸福村#k。你准备好了吗？");
        } else {
            cm.getPlayer().saveLocation("HAPPYVILLE");
            cm.warp(209000000, 0);
            cm.dispose();
        }
    }
}

