    for (var i = 0; i < chances.length; i++) {
        totalodds += chances[i];
    }
    var randomPick = Math.floor(Math.random() * totalodds) + 1;
    for (var i = 0; i < chances.length; i++) {
        randomPick -= chances[i];
        if (randomPick <= 0) {
            choice = i;
            randomPick = totalodds + 100;
        }
    }
    if (cm.isQuestStarted(2050)) {
        cm.gainItem(4031020, 1);
    }
    cm.gainItem(prizes[choice], 1);
    cm.warp(101000000, 0);
    cm.dispose();
}

