                    cm.gainMeso(-haircolorprice);
                    cm.gainItem(5151003, 1);
                    cm.sendOk("享受！");
                } else {
                    cm.sendOk("你没有足够的金币来购买优惠券！");
                }
            }
        }
    }
}

