        if (cm.isQuestActive(2314) && cm.getQuestProgressInt(2314) == 0) level2314();
        else if (cm.haveItem(2430014)) level2430014();
        else leveldispose();
    } else if(MapId == 106020500) { //城墙中央
        if(cm.isQuestActive(2322) && cm.getQuestProgressInt(2322) == 0) level2322();
