var pay = 2000;
var ticket = 4031134;
var msg;
var check;

var status = 0;

function start() {
    cm.sendSimple("你听说过那个可以欣赏到壮观海景的海滩吗，它叫做 #b#m110000000##k，离 #m" + cm.getPlayer().getMapId() + "# 有一点距离。我可以带你去那里，只需要 #b" + pay + " 冒险币#k，或者如果你带了 #b#t" + ticket + "##k，那就可以免费进去。\r\n\r\n#L0##b我付 " + pay + " 冒险币.#k#l\r\n#L1##b我有 #t" + ticket + "##k#l\r\n#L2##b#t" + ticket + "# 是什么？#k#l");
}

function action(mode, type, selection) {
    if (mode == -1 || (mode == 0 && status == 0)) {
        cm.dispose();
    } else {
        if (mode == 0 && status == 1) {
            cm.sendNext("你一定有一些事情要处理。你一定因为旅行和打猎而感到疲倦。去休息一下，如果你改变主意了，再来找我谈谈吧。");
            cm.dispose();
            return;
        }
        if (mode == 1) {
            status++;
        } else {
            status--;
        }
        if (status == 1) {
            if (selection == 0 || selection == 1) {
                check = selection;
                if (selection == 0) {
                    msg = "你想支付#b"+pay+"金币#k去往#m110000000#?";
                } else if (selection == 1) {
                    msg = "你有#b#t"+ticket+"##k?那么你可以随时去#m110000000#.";
                }
                 cm.sendYesNo(msg+"好的!!确认现在出发去#m110000000#吗?");
            } else if (selection == 2) {
                cm.sendNext("你一定对#b#t" + ticket + "##k很好奇。是的，我能理解。#t" + ticket + "#是一种物品，只要你拥有它，就可以免费前往#m110000000#。这是一种非常稀有的物品，我们甚至不得不购买，但不幸的是，我在几个星期前的一个周末丢失了。");
                status = 3;
            }
        } else if (status == 2) {
            var access = false;
            if (check == 0) {
                if (cm.getMeso() < pay) {
                    cm.sendOk("我觉得你缺少冒险币。你知道，有很多方法可以赚钱，比如……卖掉你的盔甲……打败怪物……做任务……你知道我在说什么。");
                    cm.dispose();
                } else {
                    cm.gainMeso(-pay);
                    access = true;
                }
            } else if (check == 1) {
                if (!cm.haveItem(ticket)) {
                    cm.sendOk("嗯，#b#t" + ticket + "##k到底在哪里呢？你确定你有它们吗？请再检查一遍。");
                    cm.dispose();
                } else {
                    access = true;
                }
            }
            if (access) {
                cm.getPlayer().saveLocation("FLORINA");
                cm.warp(110000000, "st00");
                cm.dispose();
            }
        } else if (status == 3) {
            cm.sendNext("你一定对#b#t" + ticket + "##k很好奇。是的，我能理解。#t" + ticket + "#是一种物品，只要你拥有它，就可以免费前往#m110000000#。这是一种非常稀有的物品，我们甚至不得不购买，但不幸的是，我在几个星期前的一个周末丢失了。");
        } else if (status == 4) {
            cm.sendPrev("我回来的时候没有带它，没有它感觉很糟糕。希望有人把它捡起来放在安全的地方。不管怎么说，这是我的故事，谁知道呢，你也许能把它捡起来好好利用。如果你有什么问题，尽管问");
        } else if (status == 5) {
            cm.dispose();
        }

    }
}

