/* Chico
	Lidibrium : Ludibrium Village (2040014)

	Refining NPC: 
	* Omok sets - Set 2
	* Match of cards
*/

var status = -1;
var selectedType = -1;
var selectedItem = -1;
var item;
var mats;
var matQty;
var cost;
var qty;

var items = [4080100, 4080006, 4080007, 4080008, 4080009, 4080010, 4080011];
var matSet = [[4030012], [4030009, 4030013, 4030014], [4030009, 4030013, 4030016], [4030009, 4030014, 4030016], [4030009, 4030015, 4030013], [4030009, 4030015, 4030014], [4030009, 4030015, 4030016]];
var matQtySet = [[99], [1, 99, 99], [1, 99, 99], [1, 99, 99], [1, 99, 99], [1, 99, 99], [1, 99, 99]];
var costSet = [10000, 25000, 25000, 25000, 25000, 25000, 25000];

function start() {
    cm.getPlayer().setCS(true);
    var selStr = "你好!我是#p2040014#, 小游戏的专家.你想玩什么游戏? #b"
    var options = ["#i4080100# #t4080100#", "#i4080006# #t4080006#", "#i4080007# #t4080007#", "#i4080008# #t4080008#", "#i4080009# #t4080009#", "#i4080010# #t4080010#", "#i4080011# #t4080011#"];
    for (var i = 0; i < options.length; i++) {
        selStr += "\r\n#L" + i + "# " + options[i] + "#l";
    }
    cm.sendSimple(selStr);
}

function action(mode, type, selection) {
    status++;
    if (mode != 1) {
        cm.dispose();
        return;
    }
    if (status == 0) {
        selectedItem = selection;

        item = items[selectedItem];
        mats = matSet[selectedItem];
        matQty = matQtySet[selectedItem];
        cost = costSet[selectedItem];
        qty = 1;

        var prompt = "我们要做";
        if (qty == 1) {
            prompt += "一个#t" + item + "#";
        } else {
            prompt += qty + " #t" + item + "#";
        }
        prompt += ",对吗? 我需要这些材料，请确保背包空间足够#b";
        if (mats instanceof Array) {
            for (var i = 0; i < mats.length; i++) {
                prompt += "\r\n#i" + mats[i] + "# " + (matQty[i] * qty) + " #t" + mats[i] + "#";
            }
        } else {
            prompt += "\r\n#i" + mats + "# " + (matQty * qty) + " #t" + mats + "#";
        }
        if (cost > 0) {
            prompt += "\r\n#i4031138# " + (cost * qty) + "金币";
        }
        cm.sendYesNo(prompt);
    } else if (status == 1) {
        var complete = true;

        if (cm.getMeso() < (cost * qty)) {
            cm.sendOk("看，我需要明确我的工资来支持我的职业生涯，这是不能绕过的。一旦你有了钱，我会很乐意帮助你。");
            cm.dispose();
            return;
        } else {
            if (mats instanceof Array) {
                for (var i = 0; complete && i < mats.length; i++) {
                    if (!cm.haveItem(mats[i], matQty[i] * qty)) {
                        complete = false;
                    }
                }
            } else if (!cm.haveItem(mats, matQty * qty)) {
                complete = false;
            }
        }
        if (!complete) {
            cm.sendOk("您缺少了一些用于制作的物品。请提供它们，以便我们可以组装游戏套装。");
        } else {
            if (cm.canHold(item, qty)) {
                if (mats instanceof Array) {
                    for (var i = 0; i < mats.length; i++) {
                        cm.gainItem(mats[i], -(matQty[i] * qty));
                    }
                } else {
                    cm.gainItem(mats, -(matQty * qty));
                }
                cm.gainMeso(-(cost * qty));

                cm.gainItem(item, qty);
                cm.sendOk("这是你的游戏设置。玩得开心！");
            } else {
                cm.sendOk("如果你的物品其他栏没有空间，我就无法为你制作套装。请先腾出空间，然后再和我交谈。");
            }
        }

        cm.dispose();
    }
}

