            var selStr = "好的，那你想让哪件魔法师武器承载龙之力？#b";
            var weapon = ["佘太君龙杖#k - 108级 魔杖#b", "黑精灵王杖#k - 110级 法杖#b"];
            for (var i = 0; i < weapon.length; i++) {
