            var weapon = ["蝉翼龙牙破#k - 110级 力量型匕首#b", "半月龙鳞裂#k - 110级 运气型匕首#b", "寒木升龙拳#k - 110级 飞镖#b"]; // Claw：盗贼使用的飞镖武器
			for (var i = 0; i < weapon.length; i++) {
