            cm.dispose();
            return;
        } else if (cm.getMeso() < cost) {
            cm.sendOk("你没有满足我需要的物资。");
            cm.dispose();
            return;
        } else {
            if (mats instanceof Array) {
                for (var i = 0; complete && i < mats.length; i++) {
                    if (!cm.haveItem(mats[i], matQty[i])) {
                        complete = false;
                    }
