                    cm.gainItem(item, 1, true, true);
                    cm.sendOk("过程已经完成。好好对待你的武器，免得招惹龙的愤怒。");
                } else {
                    cm.sendOk("不幸的是，龙的精华与你的武器产生了冲突。对你的损失我深感抱歉。");
                }
            } else {//just give basic item
                cm.gainItem(item, 1);
                cm.sendOk("过程已经完成。好好对待你的武器，免得招惹龙的愤怒。");
            }
        }
        cm.dispose();
    }
}

function getStimID(equipID) {
    var cat = Math.floor(equipID / 10000);
    switch (cat) {
        case 130: //1h sword
            return 4130002;
        case 131: //1h axe
            return 4130003;
        case 132: //1h bw
            return 4130004;
        case 140: //2h sword
            return 4130005;
        case 141: //2h axe
            return 4130006;
        case 142: //2h bw
            return 4130007;
        case 143: //spear
            return 4130008;
        case 144: //polearm
            return 4130009;
        case 137: //wand
            return 4130010;
        case 138: //staff
            return 4130011;
        case 145: //bow
            return 4130012;
        case 146: //xbow
            return 4130013;
        case 148: //knuckle
            return 4130016;
        case 149: //pistol
            return 4130017;
        case 133: //dagger
            return 4130014;
        case 147: //claw
            return 4130015;
    }
    return 4130002;
}

