 * @type {boolean}
 */
var disabled = false;
var belts = Array(1132000, 1132112, 1132113, 1132114, 1132115);
var belt_level = Array(25, 35, 45, 60, 75);
var belt_on_inventory;
var belt_points;

var status = -1;
var selectedMenu = -1;
var dojoWarp = 0;

function start() {
    if (disabled) {
        cm.sendOk("我的师傅要求现在关闭道馆，所以我不能让你进去。");
        cm.dispose();
        return;
    }

    const GameConfig = Java.type('org.gms.config.GameConfig');
    belt_points = GameConfig.getServerBoolean("use_fast_dojo_upgrade") ? Array(10, 90, 200, 460, 850) : Array(200, 1000, 2000, 3500, 5000);

    belt_on_inventory = [];
    for (var i = 0; i < belts.length; i++) {
        belt_on_inventory.push(cm.haveItemWithId(belts[i], true));
    }

    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode == -1) {
        cm.getPlayer().setDojoStage(dojoWarp);
        cm.dispose();
    } else {
        if (mode == 0) {
            cm.dispose();
            return;
        }
        if (mode == 1) {
            status++;
        }

        if (status == 0) {
            if (isRestingSpot(cm.getPlayer().getMap().getId())) {
                var text = "真没想到你可以挑战到这里!但是从现在开始就没那么容易了.要继续挑战吗?\r\n\r\n#b#L0#我要继续#l\r\n#L1#我要离开#l\r\n";

