                    } else {
                        if (mode == 0) {
                            cm.sendNext("你觉得你还能再走得更高吗？祝你好运！");
                        } else if (cm.getPlayer().getDojoStage() == Math.floor(cm.getMapId() / 100) % 100) {
                            cm.sendOk("你的进度已经被记录下来。下次挑战道馆时，你可以回到这个点。");
