 */

var status;

function start() {
    status = -1;
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode == -1) {
        cm.dispose();
    } else {
        if (mode == 0 && status == 0) {
            cm.dispose();
            return;
        }
        if (mode == 1) {
            status++;
        } else {
            status--;
        }

        var eim = cm.getEventInstance();

        if (!eim.isEventCleared()) {
            if (status == 0) {
                if (eim.getIntProperty("npcShocked") == 0 && cm.haveItem(4001130, 1)) {
                    cm.gainItem(4001130, -1);
                    eim.setIntProperty("npcShocked", 1);

                    cm.sendNext("哦？你给我信？像这样的时候，应该是什么…… 哇！伙计们，有大事发生了。集合起来，从现在开始，事情会比以往更加艰难！");
                    eim.dropMessage(6, "朱丽叶看了罗密欧的信，似乎很震惊。");

                    cm.dispose();

                } else if (eim.getIntProperty("statusStg4") == 1) {
                    var door = cm.getMap().getReactorByName("jnr3_out3");

                    if (door.getState() == 0) {
                        cm.sendNext("让我为你开门。");
                        door.hitReactor(cm.getClient());
                    } else {
                        cm.sendNext("请快点，罗密欧有麻烦了。");
                    }

                    cm.dispose();

                } else if (cm.haveItem(4001134, 1) && cm.haveItem(4001135, 1)) {
                    if (cm.isEventLeader()) {
                        cm.gainItem(4001134, -1);
                        cm.gainItem(4001135, -1);
                        cm.sendNext("太好了！你手头上有卡帕莱特和蒙特鸠的文件。现在我们可以继续了。");

                        eim.showClearEffect();
                        eim.giveEventPlayersStageReward(4);
                        eim.setIntProperty("statusStg4", 1);

                        cm.getMap().killAllMonsters();
                        cm.getMap().getReactorByName("jnr3_out3").hitReactor(cm.getClient());
                    } else {
                        cm.sendOk("请让你们的队长把文件传给我。");
                    }

                    cm.dispose();

                } else {
                    cm.sendYesNo("我们必须继续战斗，拯救罗密欧，请保持你的速度。如果你感觉不太好，无法继续，你的同伴和我都会理解……那么，你打算撤退吗？");
                }
            } else {
                cm.warp(926110700, 0);
                cm.dispose();
            }
        } else {
            if (status == 0) {
                if (eim.getIntProperty("escortFail") == 0) {
                    cm.sendNext("最终，罗密欧安全了！多亏了你的努力，我们才能将他从尤莱特的魔爪中解救出来，尤莱特现在将因为反抗马加提亚而受到审判。从现在开始，他将开始接受康复治疗，我们将密切关注他的努力，确保他将不再在未来制造麻烦。");
                } else {
                    cm.sendNext("罗密欧现在安全了，尽管战斗对他造成了一定的伤害...多亏了你们的努力，我们才能将他从尤利特的魔爪中解救出来，尤利特现在将因其反抗马加提亚而受到审判。谢谢你们。");
                    status = 2;
                }
            } else if (status == 1) {
                cm.sendNext("现在，请将这份礼物视为我们对你的感激之情的接受表示。");
            } else if (status == 2) {
                if (cm.canHold(4001160)) {
                    cm.gainItem(4001160, 1);
	    cm.gainExp(160000);

                    if (eim.getIntProperty("normalClear") == 1) {
                        cm.warp(926110600, 0);
                    } else {
                        cm.warp(926110500, 0);
                    }
                } else {
                    cm.sendOk("确保你的背包其他栏有空间。");
                }

                cm.dispose();
            } else {
                cm.warp(926110600, 0);
                cm.dispose();
            }
        }
    }
}

