    32: [-26479, "擊退搜索型T無人機A型200隻"],
    33: [-26478, "擊退搜索型T無人機B型200隻"],
    34: [-26477, "擊退戰鬥型T無人機A型200隻"],
    35: [-26476, "擊退戰鬥型T無人機B型200隻"],
    36: [-26475, "擊退殲滅型T無人機A型200隻"],
