/* 
	Hypnotize skill quest
 */

var status = -1;

function end(mode, type, selection) {
    if (mode == -1) {
        qm.dispose();
    } else {
        if(mode == 0 && type > 0) {
            qm.dispose();
            return;
        }

        if (mode == 1)
            status++;
        else
            status--;

        if (status == 0) {
            if (qm.getQuestProgress(6410, 0) == 0 && qm.getPlayer().getMapId() != 925010400 ) {
                qm.sendOk("你必须先保护#r#p2095000##k！");
                qm.dispose();
            } else {
                qm.sendNext("再次感谢你救了我。我不知道该怎么报答你。秀林茨和你都是我遇到过的最好的人。如果你像对待我一样对待怪物们，他们也可能最终成为你的朋友。请永远不要失去你内心的善良。");
            }
        } else if (status == 1) {
            qm.sendNext("(与怪物们为友…永远不要失去善意。)\r\n\r\n  #s5221009#    #b#q5221009##k");
        } else if (status == 2) {
            qm.gainExp(1200000);
            qm.teachSkill(5221009, 0, 10, -1);

            qm.forceCompleteQuest();
            qm.dispose();
        }
    }
}

