        }
        var eim = cm.getPlayer().getEventInstance();
        var nthtext = "最终";
        if (status == 0) {
            party = eim.getPlayers();
            preamble = eim.getProperty("leader" + nthtext + "preamble");
            mobcount = eim.getProperty("leader" + nthtext + "mobcount");
