        if (mode == 1) {
            status++;
        } else {
            status--;
        }
    }
    if (status == 0) {
        if (selection == 0) {
            cm.sendYesNo("如果你现在离开，接下来的24小时内你将无法参与这个活动。你确定要离开吗？");
        } else if (selection == 1) {
            if (cm.getMesos < 1 && !cm.canHold(1322005)) {
                cm.sendOk("你的金币不够，或者你的背包没有空间。");
                cm.dispose();
            } else {
                cm.gainItem(1322005);
                cm.gainMeso(-1);
                cm.dispose();
            }
        }
    } else if (status == 1) {
        if (cm.getEvent() != null) {
            cm.getEvent().addLimit();
        }
        cm.warp(109050001, 0);
        cm.dispose();
    }
}

