//获取装备类型
function getItemType(itemid) {
	var type = Math.floor(itemid/10000);
	switch (type) {
		case 100:
			return 0;  //帽子
		case 104:
			return 1;  //上衣
		case 105:
			return 2;  //套装
		case 106:
			return 3;  //裤裙
		case 107:
			return 4;  //鞋子
		case 108: 
			return 5;  //手套
		case 110:
			return 6;  //披风
		case 111:
			return 8;  //戒指
		default:
			if (type==120)
				return 999;
			if (type==135)
				return 999;
			var type=Math.floor(type/10);
			if (type==12 || type==13 || type==14 || type==15 || type==17) {
				return 7;  //武器
			}
			return 999; 
	}
}

//获取商店列表
function getItemList() {
	var conn = cm.getConnection();
	var sql = "select itemid, itemprice from npccashshopdajieda order by id desc, itemprice asc";
	var pstmt = conn.prepareStatement(sql);
	var rs = pstmt.executeQuery();
	var rsList = Array();
	while(rs.next())
	{
		rsList.push(Array(rs.getInt("itemid"), rs.getInt("itemprice")));
	}
	rs.close();
	pstmt.close();
	//conn.close();
	return rsList;
}
function getItemListByName(name) {
	var conn = cm.getConnection();
	name = name.replace(".*([';]+|(--)+).*", " ");
	var sql = "select itemid, itemprice from npccashshopdajieda where itemname like '%"+name+"%' order by id desc, itemprice asc";
	var pstmt = conn.prepareStatement(sql);
	var rs = pstmt.executeQuery();
	var rsList = Array();
	while(rs.next())
	{
		rsList.push(Array(rs.getInt("itemid"), rs.getInt("itemprice")));
	}
	rs.close();
	pstmt.close();
	//conn.close();
	return rsList;
}

