        addTravelMap('东方神州','上海外滩',701000000,1,10000,[
            '上海外滩是上海市的标志性景点之一，以其壮丽的天际线而闻名。这里是黄浦江畔的一条长堤路，两旁矗立着众多历史建筑和现代化摩天大楼。',
