                cm.removeAll(4001024);
                var prev = eim.setProperty("bossclear", "true");
                if (prev == null) {
                    var start = parseInt(eim.getProperty("entryTimestamp"));
                    var diff = Date.now() - start;

                    var points = 1000 - Math.floor(diff / (100 * 60));
                    if (points < 100) {
