function start() {
    area = cm.getMapId() % 10;
    status = -1;
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode == -1) {
        cm.dispose();
    } else {
        if (mode == 0 && type > 0) {
            cm.dispose();
            return;
        }
        if (mode == 1) {
            status++;
        } else {
            status--;
        }

        if (status == 0) {
            if (area > 0) {
                cm.sendYesNo("你希望离开这个地方吗？");
            } else {
                cm.sendYesNo("你想要回到 #b幸福村#k 吗？");
            }
        } else {
            if (area > 0) {
                cm.warp(cm.getMapId() + 1, 0);
            } else {
                cm.warp(209000000);
            }

            cm.dispose();
        }
    }
}

npc/9110000:
var status = 0;
var cost = 3000;
function start() {
    cm.sendYesNo("请问是否想去日本神社?? 3000金币一次~~~~");
}

function action(mode, type, selection) {
    if (mode != 1) {
        if (mode == 0)
        cm.sendOk("既然你不要那就算了~~~");
        cm.dispose();
        return;
    }
    status++;
    if (status == 1) {
		if(cm.getMeso() < cost) {
		cm.sendOk("没钱还要去日本神社吗?");
		cm.dispose();
		} else {
		cm.gainMeso(-cost);
		cm.warp(800000000, 0);
        cm.dispose();
    }
}
}

