                cm.warp(801040004, 1);
                cm.dispose();
            }
        } else {
            if (status == 0) {
                cm.sendNext("你们做到了，干得漂亮！现在我们的城市摆脱了那些暴徒的暴政！作为城市的代表，请接受这份奖励，作为对你们努力的认可，我会把你们带回城里。");
            }

            if (status == 1) {
                var eim = cm.getEventInstance();
                if (!eim.giveEventReward(cm.getPlayer())) {
                    cm.sendNext("请先在您的物品栏腾出空间…");
                } else {
                    cm.warp(801040101);
                }

                cm.dispose();
            }
        }
    }
}

