var PRINCESS_NO_TICKET = 4000699;
var Quest = Java.type("org.gms.server.quest.Quest");

var status = -1;
var selectingReward = false;

function mobList() {
    return (
        "枫叶丘陵田野里的织田残党太多了。去击杀以下怪物各#r200#k只：\r\n\r\n" +
        "#b#o9421511##k\r\n" +
        "#b#o9421512##k\r\n" +
        "#b#o9421513##k\r\n" +
        "#b#o9421514##k\r\n\r\n" +
