                "干得漂亮。请选择一张挑战门票：\r\n" +
                "#b#L0##i" + RANMARU_TICKET + "# #t" + RANMARU_TICKET + "##l\r\n" +
                "#L1##i" + PRINCESS_NO_TICKET + "# #t" + PRINCESS_NO_TICKET + "##l"
            );
            return;
        }
        if (cm.getQuestStatus(QUEST_ID) == 1) {
            cm.sendOk("还没清完田野。继续击杀以下怪物各200只：\r\n#o9421511#\r\n#o9421512#\r\n#o9421513#\r\n#o9421514#");
            cm.dispose();
            return;
        }
        if (quest.canStart(player, NPC_ID)) {
            cm.sendYesNo(mobList());
            return;
        }
        if (cm.isQuestCompleted(QUEST_ID)) {
            cm.sendOk("今天的清剿委托已经完成了，明天再来吧。");
            cm.dispose();
            return;
        }
        cm.sendOk("120级以上才能接受枫叶丘陵的清剿委托。");
        cm.dispose();
        return;
    }
    if (selectingReward) {
        var ticket = selection == 1 ? PRINCESS_NO_TICKET : RANMARU_TICKET;
        if (!quest.canComplete(player, NPC_ID)) {
            cm.sendOk("这个每日委托目前无法完成。");
            cm.dispose();
            return;
        }
        if (!cm.canHold(ticket, 1)) {
            cm.sendOk("请先在其他栏背包中留出一个空位。");
            cm.dispose();
            return;
        }
        quest.complete(player, NPC_ID);
        cm.gainItem(ticket, 1);
        cm.sendOk("已领取#b#t" + ticket + "##k。");
        cm.dispose();
        return;
    }
    quest.start(player, NPC_ID);
    cm.sendOk("去枫叶丘陵田野清剿织田残党，打完再回来找我。");
    cm.dispose();
}

npc/9130100:
var TICKET = 4000699;
var status = -1;

function start() { status = -1; action(1, 0, 0); }

function action(mode, type, selection) {
    if (mode != 1) { cm.dispose(); return; }
    status++;
    if (status == 0) {
        if (!cm.haveItem(TICKET, 1)) {
            cm.sendOk("挑战浓姬需要#b#t" + TICKET + "##k。完成枫叶丘陵#b#p9130000##k的每日清剿并选择浓姬门票即可获得。");
            cm.dispose();
            return;
        }
        cm.sendYesNo("浓姬盘踞在比叡山本堂深处。要现在前往讨伐吗？");
        return;
    }
    if (!cm.haveItem(TICKET, 1)) {
        cm.sendOk("需要持有#b#t" + TICKET + "##k才能进入。");
        cm.dispose();
        return;
    }
    var em = cm.getEventManager("PrincessNoBattle");
    if (em == null) { cm.sendOk("浓姬讨伐目前无法开启。"); cm.dispose(); return; }
    var started;
    if (cm.getParty() != null) {
        if (!cm.isLeader()) {
            cm.sendOk("请让队长与我对话开启浓姬讨伐。");
            cm.dispose();
            return;
        }
        var eligible = em.getEligibleParty(cm.getParty());
        if (eligible.size() < 1 || eligible.size() > 6) {
            cm.sendOk("队伍成员需要在当前地图，等级达到160级，且队伍人数为1至6人。");
            cm.dispose();
            return;
        }
        started = em.startInstance(cm.getParty(), cm.getPlayer().getMap(), 1);
    } else {
        started = em.startInstance(cm.getPlayer());
    }
    if (!started) {
        cm.sendOk("已有队伍正在挑战，请稍后再试。");
        cm.dispose();
        return;
    }
    cm.gainItem(TICKET, -1);
    cm.dispose();
}

