}

function action(mode, type, selection) {
    if (mode < 1) {  // disposing issue with stylishs found thanks to Vcoc
        cm.dispose();
    } else {
        if (mode == 1) {
            status++;
        } else {
            status--;
        }
        if (status == 0) {
            cm.sendSimple("你好，我是Rhomes博士，是天空之城整形外科店的美瞳部门主任。\r\n我的目标是通过美瞳的奇迹为每个人的眼睛增添个性，而且通过#b#t5152011##k或者#b#t5152014##k，我也可以为你做同样的事情！现在，你想要使用哪个？\r\n#L1#美瞳：#i5152011##t5152011##l\r\n#L2#美瞳：#i5152014##t5152014##l\r\n#L3#一次性美瞳：#i5152104#（任何颜色）#l");
        } else if (status == 1) {
            if (selection == 1) {
                beauty = 1;
                selectedRegularCoupon()
            } else if (selection == 2) {
                beauty = 2;
                selectedVipCoupon()
            } else if (selection == 3) {
                beauty = 3;
                selectedOneTimeCoupon()
            }
        } else if (status == 2) {
            cm.dispose();
            if (beauty == 1) {
                acceptedRegularCoupon()
            } else if (beauty == 2) {
                selectedVipStyle(selection)
            } else if (beauty == 3) {
                selectedOneTimeStyle(selection)
            }
        }
    }
}

function selectedRegularCoupon() {
    if (cm.getPlayer().getGender() == 0) {
        var current = cm.getPlayer().getFace() % 100 + 20000;
    }
    if (cm.getPlayer().getGender() == 1) {
        var current = cm.getPlayer().getFace() % 100 + 21000;
    }
    colors = Array();
    pushIfItemsExists(colors, [current + 100, current + 300, current + 400, current + 700]);
