var status = 0;
var MySelection = -1;

function start() {
    cm.sendSimple("我是勇者阿莫斯。你想做什么？\r\n#b#L0#参加婚礼村挑战！#l\r\n#L1#用5把钥匙交换门票！#l\r\n#k");
}

function action(mode, type, selection) {
    if (mode == -1) {
        cm.dispose();
    } else {
        if (status >= 0 && mode == 0) {
            cm.sendOk("好的，当你准备好的时候再回来。");
            cm.dispose();
            return;
        }
        if (mode == 1) {
            status++;
        } else {
            status--;
        }
        if (status == 1 && selection == 0) {
            if (cm.haveItem(4031592, 1)) {
                cm.sendYesNo("所以你想进入 #b入口#k？");
                MySelection = selection;
            } else {
                cm.sendOk("您必须有入场券才能进入。");
                cm.dispose();
            }
        } else if (status == 1 && selection == 1) {
            if (cm.haveItem(4031592)) {
                cm.sendOk("你已经有一张入场券了！");
                cm.dispose();
            } else if (cm.haveItem(4031593, 10)) {
                cm.sendYesNo("所以你想要一张门票？");
                MySelection = selection;
            } else {
                cm.sendOk("请先给我拿到5把钥匙！");
                cm.dispose();
            }
        } else if (status == 2 && MySelection == 0) {
            cm.warp(670010100, 0);
            cm.gainItem(4031592, -1)
            cm.dispose();
        } else if (status == 2 && MySelection == 1) {
            cm.gainItem(4031593, -5);
            cm.gainItem(4031592, 1);
            cm.dispose();
        }
    }
}

