function action(mode, type, selection) {
    if (mode != 1) {
        cm.dispose();
        return;
    }
    status++;
    if (status == 0) {
        var text = "欢迎来到锻造系统，我什么都能造！客官请选择你要锻造的装备#b";
        var options = ["不速之客系列", "乌特格鲁德系列"];
        for (var i = 0; i < options.length; i++) {
            text += "\r\n#L" + i + "# " + options[i] + "#l";
        }
        cm.sendSimple(text);
    } else if (status == 1) {
        series = selection;
        if (series == 0) {
            var sel = "不速之客系列请选择阶段：#b";
            var tiers = ["第一系列", "第二系列", "第三系列", "最终系列", "至尊系列"];
            for (var t = 0; t < tiers.length; t++) {
                sel += "\r\n#L" + t + "# " + tiers[t] + "#l";
            }
            cm.sendSimple(sel);
        } else if (series == 1) {
            sendWeaponList(UTGARD);
        }  
    } else if (status == 2) {
        if (series == 0) {
            guestTier = selection;
            sendWeaponList(GUEST[guestTier]);
        } else {
            setUtgardRecipe(selection);
            sendConfirm();
        }
    } else if (status == 3) {
        if (series == 0) {
            setGuestRecipe(selection);
            sendConfirm();
        } else {
            doCraft();
        }
    } else if (status == 4) {
        doCraft();
    } else {
        cm.dispose();
    }
}

function sendWeaponList(list) {
    var sel = "请选择要锻造的装备：#b";
