status = -1;
oldSelection = -1;

function start() {
    cm.sendSimple("你好，我是来自新加坡机场的#p9270041#。我可以帮助你迅速到达新加坡。你想去新加坡吗？\r\n#b#L0#我想买一张去新加坡的飞机票\r\n#b#L1#让我进入出发点。");
}

function action(mode, type, selection) {
    status++;
    if (mode <= 0) {
        oldSelection = -1;
        cm.dispose();
    }

    if (status == 0) {
        if (selection == 0) {
            cm.sendYesNo("门票的价格是5,000金币。你要购买门票吗？");
        } else if (selection == 1) {
            cm.sendYesNo("您现在想要进去吗？一旦您进去，您的票就会作废！感谢您选择北斗航空。");
        }
        oldSelection = selection;
    } else if (status == 1) {
        if (oldSelection == 0) {
            if (cm.getPlayer().getMeso() > 4999 && !cm.getPlayer().haveItem(4031731)) {
                if (cm.canHold(4031731, 1)) {
                    cm.gainMeso(-5000);
                    cm.gainItem(4031731);
                    cm.sendOk("谢谢您选择北斗航空！祝您旅途愉快！");
                    cm.dispose();
                } else {
                    cm.sendOk("你的其他栏没有空闲的位置来放置这张票，请提前留一个位置。");
                    cm.dispose();
                }
            } else {
                cm.sendOk("您没有足够的金币或者您已经购买了一张门票。");
                cm.dispose();
            }
        } else if (oldSelection == 1) {
            if (cm.itemQuantity(4031731) > 0) {
                var em = cm.getEventManager("AirPlane");
                if (em.getProperty("entry") == "true") {
                    cm.warp(540010100);
                    cm.gainItem(4031731, -1);
                } else {
                    cm.sendOk("抱歉，飞机已经起飞，请稍等几分钟。");
                }
            } else {
                cm.sendOk("你需要一张#b#t4031731##k才能登上飞机！");
            }
        }
        cm.dispose();
    }
}

