    { item: 1322223, price: 400, name: "漩涡锤" },
    { item: 1332247, price: 400, name: "漩涡匕首" },
    { item: 1372195, price: 400, name: "漩涡短杖" },
    { item: 1382231, price: 400, name: "漩涡长杖" },
    { item: 1402220, price: 400, name: "漩涡双手剑" },
