    text += "#L1##b椅子#k（每把 " + CHAIR_PRICE + " 点券）#l\r\n";
    text += "#L2##b至高无上·逼王戒#k#l\r\n";
    text += "#L3##b伤害皮肤#k#l\r\n";
    text += "#L4##b坐骑领取#k#l";
    cm.sendSimple(text);
}

function showDamageSkinPage() {
    if (damageSkinIds === null || damageSkinIds.length === 0) {
        cm.sendOk("当前没有可用的伤害皮肤。");
        cm.dispose();
        return;
    }

    var pageCount = Math.ceil(damageSkinIds.length / DAMAGE_SKIN_PAGE_SIZE);
    if (damageSkinPage < 0 || damageSkinPage >= pageCount) {
        rejectInvalidSelection();
        return;
    }

    var currentSkin = cm.getDamageSkinId();
    var startIndex = damageSkinPage * DAMAGE_SKIN_PAGE_SIZE;
    var endIndex = Math.min(startIndex + DAMAGE_SKIN_PAGE_SIZE, damageSkinIds.length);
    var text = "#e伤害皮肤#n  #d第 " + (damageSkinPage + 1) + "/" + pageCount + " 页#k\r\n";
    text += "点击预览即可立即更换。\r\n\r\n";
    for (var i = startIndex; i < endIndex; i++) {
        var skinId = damageSkinIds[i];
        var selected = skinId === currentSkin ? " #r[使用中]#k" : "";
        text += "#L" + i + "##fEffect/DamageSkin.img/preview/" + skinId + "#\r\n";
        text += "#b" + cm.getDamageSkinName(skinId) + "#k" + selected + "#l\r\n";
    }
    if (damageSkinPage > 0) {
        text += "#L" + PREVIOUS_PAGE + "##b上一页#k#l  ";
    }
    if (damageSkinPage + 1 < pageCount) {
        text += "#L" + NEXT_PAGE + "##b下一页#k#l  ";
    }
    text += "#L" + BACK_TO_MAIN + "##d返回主菜单#k#l";
    cm.sendSimple(text);
}

function handleDamageSkinSelection(selection) {
    var pageCount = Math.ceil(damageSkinIds.length / DAMAGE_SKIN_PAGE_SIZE);
    if (selection === PREVIOUS_PAGE && damageSkinPage > 0) {
        damageSkinPage--;
        showDamageSkinPage();
        return;
    }
    if (selection === NEXT_PAGE && damageSkinPage + 1 < pageCount) {
        damageSkinPage++;
        showDamageSkinPage();
        return;
    }
    if (selection === BACK_TO_MAIN) {
        stage = "main";
        showMainMenu();
        return;
    }

    var startIndex = damageSkinPage * DAMAGE_SKIN_PAGE_SIZE;
    var endIndex = Math.min(startIndex + DAMAGE_SKIN_PAGE_SIZE, damageSkinIds.length);
    if (selection < startIndex || selection >= endIndex) {
        rejectInvalidSelection();
        return;
    }
    var skinId = damageSkinIds[selection];
    if (!cm.setDamageSkin(skinId)) {
        cm.sendOk("伤害皮肤更换失败，请稍后重试。");
        cm.dispose();
        return;
    }
    cm.sendOk("已更换为：#b" + cm.getDamageSkinName(skinId) + "#k。\r\n\r\n#fEffect/DamageSkin.img/preview/" + skinId + "#");
    cm.dispose();
}

function showChairPage() {
    if (chairIds.length === 0) {
        cm.sendOk("当前没有可购买的椅子。");
        cm.dispose();
        return;
    }

    var pageCount = Math.ceil(chairIds.length / PAGE_SIZE);
    if (currentPage < 0 || currentPage >= pageCount) {
        rejectInvalidSelection();
        return;
    }

    var startIndex = currentPage * PAGE_SIZE;
    var endIndex = Math.min(startIndex + PAGE_SIZE, chairIds.length);
    var balance = cm.getPlayer().getCashShop().getCash(1);
    var text = "#e椅子商店#n  #d第 " + (currentPage + 1) + "/" + pageCount + " 页#k\r\n";
    text += "每把 #r" + CHAIR_PRICE + "#k 点券，当前余额：#b" + balance + "#k\r\n\r\n";

    for (var i = startIndex; i < endIndex; i++) {
        var itemId = chairIds[i];
        text += "#L" + i + "##i" + itemId + "# #b#z" + itemId + "##k#l\r\n";
    }

    text += "\r\n";
    if (currentPage > 0) {
        text += "#L" + PREVIOUS_PAGE + "##b上一页#k#l  ";
    }
    if (currentPage + 1 < pageCount) {
        text += "#L" + NEXT_PAGE + "##b下一页#k#l  ";
    }
    text += "#L" + BACK_TO_MAIN + "##d返回主菜单#k#l";
    cm.sendSimple(text);
}

function handleChairPageSelection(selection) {
    var pageCount = Math.ceil(chairIds.length / PAGE_SIZE);
    if (selection === PREVIOUS_PAGE && currentPage > 0) {
        currentPage--;
        showChairPage();
        return;
    }
    if (selection === NEXT_PAGE && currentPage + 1 < pageCount) {
        currentPage++;
        showChairPage();
        return;
    }
    if (selection === BACK_TO_MAIN) {
        stage = "main";
        showMainMenu();
        return;
    }

    var startIndex = currentPage * PAGE_SIZE;
    var endIndex = Math.min(startIndex + PAGE_SIZE, chairIds.length);
    if (selection < startIndex || selection >= endIndex) {
        rejectInvalidSelection();
        return;
    }

    selectedChair = chairIds[selection];
    if (selectedChair === FISHING_CHAIR) {
        rejectInvalidSelection();
        return;
    }

    stage = "confirm";
    var text = "确定花费 #r" + CHAIR_PRICE + "#k 点券购买以下椅子吗？\r\n\r\n";
    text += "#i" + selectedChair + "# #b#z" + selectedChair + "##k";
    cm.sendYesNo(text);
}

function purchaseChair() {
    if (!containsChair(selectedChair)) {
        rejectInvalidSelection();
        return;
    }
    if (!cm.canHold(selectedChair, 1)) {
        cm.sendOk("设置栏背包空间不足，请整理后再来。");
        cm.dispose();
        return;
    }

    var cashShop = cm.getPlayer().getCashShop();
    if (cashShop.getCash(1) < CHAIR_PRICE) {
        cm.sendOk("点券不足，需要 #r" + CHAIR_PRICE + "#k 点券。");
        cm.dispose();
        return;
    }

    cashShop.gainCash(1, -CHAIR_PRICE);
    cm.gainItem(selectedChair, 1);
    cm.sendOk("购买成功，获得 #i" + selectedChair + "# #b#z" + selectedChair + "##k。\r\n已扣除 #r" + CHAIR_PRICE + "#k 点券。");
    cm.dispose();
}

function containsChair(itemId) {
    for (var i = 0; i < chairIds.length; i++) {
        if (chairIds[i] === itemId) {
            return true;
        }
    }
    return false;
}

function rejectInvalidSelection() {
    cm.sendOk("选择无效，请重新打开对话。");
    cm.dispose();
}

