 * 单人副本，基于 Level 阶段式对话框架改写
 * 原脚本：action(d,c,b) 模式，status==0 先 dispose 再逻辑（错误消息玩家看不到）
 */

var isRepeat = true;
var EventName = 'AkayrumFSB';
var EventLevel = 255;
var PQLog = '阿卡伊勒 分身';

var entryMap = 272010000;    // 事件启动时玩家进入的初始地图
var exitMap = 272010000;     // 玩家未能完成事件时被传送至此地图
