        ]
    },
    mPark_in01: {
        key: "MPARK_MIDDLE",
        name: "中级园区",
        hint: "黄昏佩里昂到神秘河入口",
        courses: [
            [953020000, "自动警卫区域"],
            [954030000, "龙之巢穴"],
            [954040000, "忘却的神殿"],
            [954050000, "骑士团要塞"],
            [954060000, "幽灵峡谷"],
            [954070000, "消逝的旅途"],
            [954080000, "啾啾艾尔兰"],
            [954090000, "梦之都拉契尔恩"],
            [954100000, "神秘森林阿尔卡娜"],
            [954101000, "魔拉斯"],
            [954102000, "艾斯佩拉"]
        ]
    },
    mPark_in02: {
        key: "MPARK_ADVANCED",
        name: "高级园区",
        hint: "神秘河中后期与格兰蒂斯",
        courses: [
            [954103000, "塞拉斯"],
            [954104000, "月之桥"],
            [954105000, "苦痛迷宫"],
            [954106000, "利曼"],
            [954107000, "塞尔尼温"],
            [954108000, "阿尔克斯"],
            [954109000, "奥迪温"],
            [954110000, "桃源境"]
        ]
    }
};

function start() {
    status = -1;
    region = REGIONS[cm.getScriptName()];
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode <= 0) {
        cm.dispose();
        return;
    }
    status++;
    if (status == 0) {
        if (cm.getMapId() != 951000000) {
            cm.sendYesNo("要离开怪物公园吗？");
            return;
        }
        if (region == null) {
            cm.sendOk("请走大厅右边的门进入园区。\r\n#b左门#k 初级、#b中门#k 中级、#b右门#k 高级。\r\n每个园区每天可进入 #r" + DAILY_LIMIT + "#k 次，次数按门分开计算。");
            cm.dispose();
            return;
        }
        em = cm.getEventManager("MonsterPark");
        if (em == null) {
            cm.sendOk("怪物公园现在无法使用。");
            cm.dispose();
            return;
        }
        var remaining = remainingOf(cm.getPlayer());
        var menu = "这里是#b" + region.name + "#k（" + region.hint + "）。\r\n每条路线 6 关、限时 10 分钟。清完本图全部怪物后走上方传送门。\r\n今日剩余次数：#b" + remaining + "/" + DAILY_LIMIT + "#k\r\n#b";
        for (var i = 0; i < region.courses.length; i++) {
            menu += "#L" + i + "#" + region.courses[i][1] + "#l\r\n";
        }
        cm.sendSimple(menu);
    } else if (status == 1) {
        if (cm.getMapId() != 951000000) {
            cm.warp(951000000, 0);
            cm.dispose();
            return;
        }
        if (region == null || selection < 0 || selection >= region.courses.length) {
            cm.dispose();
            return;
        }
        if (cm.getLevel() < 105) {
            cm.sendOk("需要 105 级才能进入怪物公园。");
            cm.dispose();
            return;
        }
        var blocked = dailyBlockedName();
        if (blocked != null) {
            cm.sendOk(blocked + " 今天在" + region.name + "的次数已经用完（" + DAILY_LIMIT + " 次）。");
            cm.dispose();
            return;
        }
        em = cm.getEventManager("MonsterPark");
        em.setProperty("course", String(region.courses[selection][0]));
        em.setProperty("parkRegion", region.key);
        var started;
