function warpIfHeadDefeated(pi, defeatedHeadCount, targetMap) {
    if (pi.getEventInstance().getIntProperty("defeatedHead") >= defeatedHeadCount) {
        pi.playPortalSound();
        pi.warp(targetMap, 0);
        return true;
    }

