/* The five caves
 * @author Jvlaple
 */
function enter(pi) {
    var nextMap;
    var eim;
    var target;
    var targetPortal;
    var avail;

    if (pi.getPlayer().getMapId() == 240050101) {
        nextMap = 240050102;
        eim = pi.getPlayer().getEventInstance();
        target = eim.getMapInstance(nextMap);
        targetPortal = target.getPortal("sp");
        // only let people through if the eim is ready
        avail = eim.getProperty("1stageclear");
        if (avail == null) {
            // do nothing; send message to player
            pi.getPlayer().dropMessage(6, "【暗黑龙王】的封印阻挡着这扇门！");
            return false;
        } else {
            pi.playPortalSound();
            pi.getPlayer().changeMap(target, targetPortal);
            return true;
        }
    } else if (pi.getPlayer().getMapId() == 240050102) {
        nextMap = 240050103;
        eim = pi.getPlayer().getEventInstance();
        target = eim.getMapInstance(nextMap);
        targetPortal = target.getPortal("sp");
        // only let people through if the eim is ready
        avail = eim.getProperty("2stageclear");
        if (avail == null) {
            // do nothing; send message to player
            pi.getPlayer().dropMessage(6, "【暗黑龙王】的封印阻挡着这扇门！");
            return false;
        } else {
            pi.playPortalSound();
            pi.getPlayer().changeMap(target, targetPortal);
            return true;
        }
    } else if (pi.getPlayer().getMapId() == 240050103) {
        nextMap = 240050104;
        eim = pi.getPlayer().getEventInstance();
        target = eim.getMapInstance(nextMap);
        targetPortal = target.getPortal("sp");
        // only let people through if the eim is ready
        avail = eim.getProperty("3stageclear");
        if (avail == null) {
            // do nothing; send message to player
            pi.getPlayer().dropMessage(6, "【暗黑龙王】的封印阻挡着这扇门！");
            return false;
        } else {
            pi.playPortalSound();
            pi.getPlayer().changeMap(target, targetPortal);
            return true;
        }
    } else if (pi.getPlayer().getMapId() == 240050104) {
        nextMap = 240050105;
        eim = pi.getPlayer().getEventInstance();
        target = eim.getMapInstance(nextMap);
        targetPortal = target.getPortal("sp");
        // only let people through if the eim is ready
        avail = eim.getProperty("4stageclear");
        if (avail == null) {
            // do nothing; send message to player
            pi.getPlayer().dropMessage(6, "【暗黑龙王】的封印阻挡着这扇门！");
            return false;
        } else {
            pi.playPortalSound();
            pi.getPlayer().changeMap(target, targetPortal);
            return true;
        }
    } else if (pi.getPlayer().getMapId() == 240050105) {
        nextMap = 240050100;
        eim = pi.getPlayer().getEventInstance();
        target = eim.getMapInstance(nextMap);
        targetPortal = target.getPortal("st00");

        avail = eim.getProperty("5stageclear");
        if (avail == null) {
            if (pi.haveItem(4001092) && pi.isEventLeader()) {
                eim.showClearEffect();
                pi.getPlayer().dropMessage(6, "队长的红色钥匙瞬间打破了封印...");
                pi.playPortalSound();
                pi.getPlayer().changeMap(target, targetPortal);
                eim.setIntProperty("5stageclear", 1);
                return true;
            } else {
                pi.getPlayer().dropMessage(6, "【暗黑龙王】的封印阻挡着入口！需队长持有钥匙方可解除。");
                return false;
            }
        } else {
            pi.playPortalSound();
            pi.getPlayer().changeMap(target, targetPortal);
            return true;
        }
    }
    return true;
}

