function enter(pi) {
    if (pi.isEventLeader() == true) {
        var eim = pi.getPlayer().getEventInstance();
        var target;
        var theWay = pi.getMap().getReactorByName("light").getState();
        if (theWay == 1) {
            target = 240050300; //light
        } else if (theWay == 3) {
            target = 240050310; //dark
        } else {
            pi.playerMessage(5, "点击灯泡揭开你的命运！");
            return false;
        }

        pi.playPortalSound();
        eim.warpEventTeam(target);
        return true;
    } else {
        pi.playerMessage(6, "您不是队伍队长，只有队长可以通过此传送门。");
        return false;
    }
}

