                return false;
            } else {
                pi.playPortalSound();
                pi.warp(930000300, 0); //assuming they cant get past reactor without it being gone
                return true;
            }
            break;

        default:
            pi.playerMessage(5, "该传送门通往未绑定的路径。");
            return false;
    }
}

