@author Ronan
*/

function enter(pi) {
    if (pi.getMap().getMonsters().isEmpty()) {
        var nextStage;

        if (pi.getMapId() % 500 >= 100) {
            nextStage = pi.getMapId() + 100;
        } else {
            nextStage = 970030001 + (Math.floor((pi.getMapId() - 970030100) / 500));
        }

        pi.playPortalSound();
        pi.warp(nextStage);
        return true;
    } else {
        pi.getPlayer().dropMessage(6, "击败所有怪物后才能进入下一阶段");
        return false;
    }
}

