            qm.sendOk("但我不担心这些。我相信你一定能战胜这一切，保护枫树世界免受黑魔法师的伤害。当然，你必须变得比现在强一点，对吧?");
        else if (status == 3) {
            qm.gainItem(1142065, 1); // Noblesse Medal * 1
            qm.gainExp(20); //gain 20 exp!!
