        } else if (status == 2) {
            qm.sendSimple("你怎么认为？你有兴趣把自己看作骑士团的领袖吗？如果你已经决定了你想成为什么样的骑士，那么你就不必去看它了…\r\n\r\n#b#L0#让我看看我作为骑士领袖的样子.#l ..#b#L1#不，我没事.");
