            }
        } else if (status == 2) {
            qm.sendNextPrev("我给了你一些#b技能点#k。我还传授了你一些只有骑士才能掌握的灵魂大师的技能，所以我希望你能努力钻研，并尽可能地培养它们，就像培养你的灵魂一样。");
        } else if (status == 3) {
            qm.sendPrev("既然你已经正式成为皇家骑士，那就要以骑士的标准行事，这样才能维护女皇的威名。");
        } else if (status == 4) {
            qm.dispose();
        }
    }
}

