*/

var status = -1;

function start(mode, type, selection) {
    if (mode == -1) {
        qm.dispose();
    } else {
        if (mode == 0 && type > 0) {
            if (status != 3) {
                qm.sendOk("我有个请求，你愿意听我说说吗？");
                qm.dispose();
            } else {
                if (qm.canHold(4032375, 1)) {
                    qm.sendNext("你是谁？看你好像是冒险岛世界的冒险家。我们王国目前正面临巨大的危机，需要一位勇士来拯救我们。如果你没什么事的话，希望你能帮助我们。");
