/*
 *2408002.js
 *Key Warp for Horn Tail PQ [HTPQ]
 *@author Jvlaple
*/

function act() {
    var eim = rm.getPlayer().getEventInstance();
    var womanfred = eim.getMapFactory().getMap(240050100);
    var vvpMap = rm.getPlayer().getMapId();
    var vvpKey;
    var vvpOrig = 4001088;
    var vvpStage = -1;
    eim.showClearEffect(false, vvpMap);
    rm.mapMessage(6, "神秘钥匙已被传送至未知领域...");
    switch (vvpMap) {
        case 240050101 : {
            vvpKey = vvpOrig;
            vvpStage = 1;
            break;
        }
        case 240050102 : {
            vvpKey = vvpOrig + 1;
            vvpStage = 2;
            break;
        }
        case 240050103 : {
            vvpKey = vvpOrig + 2;
            vvpStage = 3;
            break;
        }
        case 240050104 : {
            vvpKey = vvpOrig + 3;
            vvpStage = 4;
            break;
        }
        default : {
            vvpKey = -1;
            break;
        }
    }

    eim.setIntProperty(vvpStage + "stageclear", 1);

    const Item = Java.type('org.gms.client.inventory.Item');
    var tehWomanfred = new Item(vvpKey, 0, 1);
    var theWomanfred = womanfred.getReactorByName("keyDrop1");
    var dropper = eim.getPlayers().get(0);
    womanfred.spawnItemDrop(theWomanfred, dropper, tehWomanfred, theWomanfred.getPosition(), true, true);
    eim.getMapInstance(240050100).dropMessage(6, "强光闪过，一把神秘钥匙随机出现在地图某处！");
}

